class FastScanner(input: InputStream) {
    private val reader = BufferedReader(InputStreamReader(input))
    private var tokenizer: StringTokenizer? = null

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            tokenizer = StringTokenizer(reader.readLine() ?: breakLoop())
        }
        return tokenizer!!.nextToken()
    }

    private fun breakLoop(): String = throwEOF()

    private fun throwEOF(): String {
        throw EOFException()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

